{
  "opening": "This release introduces significant behavioral shifts in the Lark parsing library, focusing on default configurations and error handling mechanisms. The primary changes involve the new discard strategy, updated lexer naming conventions, and adjusted argument ordering for decorators. These updates aim to improve ergonomics and performance while maintaining backward compatibility where possible.",
  "requirements": [
    {
      "id": "m03",
      "text": "The parser must correctly handle line breaks within grammar rules without raising syntax errors."
    },
    {
      "id": "m05",
      "text": "The public API must expose the renamed BasicLexer class and the 'basic' lexer option instead of the previous TraditionalLexer and 'standard' options."
    },
    {
      "id": "m07",
      "text": "The EBNF_to_BNF conversion process must generate the correct number of placeholder nodes to ensure accurate parse tree structure."
    },
    {
      "id": "m10",
      "text": "The BasicLexer class must be available as a public name for users to instantiate or reference directly."
    },
    {
      "id": "m13",
      "text": "The Lark parser must successfully load previously saved parsing states from cache files without corruption or failure."
    },
    {
      "id": "m20",
      "text": "The v_args decorator with meta=True must pass metadata as the first argument in the callback function signature."
    },
    {
      "id": "m26",
      "text": "Terminal priorities must default to 0 for both terminals and rules, replacing the previous default of 1 for terminals."
    },
    {
      "id": "m30",
      "text": "Discarding a parse node must be achieved by returning the Discard object rather than raising it as an exception."
    },
    {
      "id": "m34",
      "text": "The PythonIndenter class must be exposed publicly to allow users to indent Python-style grammars correctly."
    }
  ],
  "closing": "Please verify that all public names are accessible under their specified identifiers and that the new defaults behave as described. Ensure that existing code using the old discard mechanism is migrated to return Discard explicitly."
}
